import {
    CompatRange,
    ContentRef,
    type ContentRetentionField,
    contentRetentionFields,
    Digest,
    type JsonValue,
    RecordCodec,
    TextId
} from "../core";
import { BindingName, BindingRequirement, FacetPackageId } from "../facets";
import { WorkspaceId } from "../identity";
import {
    bindingRequirements,
    canonicalBindingRequirements,
    contentRef,
    requireExactObject,
    publicationId,
    slateId,
    versionId,
    workspaceId
} from "./codec";
import { SlateId, SlatePublicationId, SlateVersionId } from "./id";

class SlatePublicationCodecV1 extends RecordCodec<SlatePublication> {
    public constructor() {
        super(
            [
                SlatePublication,
                TextId,
                ContentRef,
                Digest,
                SlateVersionId,
                SlateId,
                SlatePublicationId,
                WorkspaceId,
                BindingName,
                BindingRequirement,
                FacetPackageId,
                CompatRange
            ],
            "slate.publication",
            {
                major: 1,
                minor: 0
            }
        );
    }

    protected encodePayload(publication: SlatePublication): JsonValue {
        return publication.toData();
    }

    protected decodePayload(payload: JsonValue): SlatePublication {
        return SlatePublication.fromData(payload);
    }
}

export class SlatePublication {
    public static get codec(): RecordCodec<SlatePublication> {
        return slatePublicationCodecInstance;
    }

    public constructor(
        public readonly id: SlatePublicationId,
        public readonly workspaceId: WorkspaceId,
        public readonly slateId: SlateId,
        public readonly versionId: SlateVersionId,
        public readonly materialization: ContentRef,
        bindings: readonly BindingRequirement[]
    ) {
        if (
            !(id instanceof SlatePublicationId) ||
            !(workspaceId instanceof WorkspaceId) ||
            !(slateId instanceof SlateId) ||
            !(versionId instanceof SlateVersionId) ||
            !(materialization instanceof ContentRef)
        ) {
            throw new TypeError("Slate publication is malformed");
        }
        this.bindings = canonicalBindingRequirements(bindings, "Slate publication bindings");
        Object.freeze(this);
    }

    /**
     * The capabilities this published Slate needs bound before it can run, declared by
     * name at publish. A declaration, never a grant: it is what a skeleton export carries
     * so a forker can read what the Slate requires before anything of theirs runs.
     */
    public readonly bindings: readonly BindingRequirement[];

    public static encode(publication: SlatePublication): Uint8Array {
        return SlatePublication.codec.encode(publication);
    }

    public static decode(bytes: Uint8Array): SlatePublication {
        return SlatePublication.codec.decode(bytes);
    }

    public toData(): JsonValue {
        return {
            bindings: this.bindings.map((requirement) => requirement.toData()),
            id: this.id.value,
            materialization: this.materialization.value,
            slateId: this.slateId.value,
            versionId: this.versionId.value,
            workspaceId: this.workspaceId.value
        };
    }

    public static fromData(payload: JsonValue): SlatePublication {
        const object = requireExactObject(
            payload,
            ["bindings", "id", "materialization", "slateId", "versionId", "workspaceId"],
            "Slate publication payload"
        );
        return new SlatePublication(
            publicationId(object["id"]),
            workspaceId(object["workspaceId"]),
            slateId(object["slateId"]),
            versionId(object["versionId"]),
            contentRef(object["materialization"], "Slate publication materialization"),
            bindingRequirements(object["bindings"], "Slate publication bindings")
        );
    }
}

const slatePublicationCodecInstance = new SlatePublicationCodecV1();

/**
 * The immutable publication bundle a deployment is cut from (§8.4).
 */
export function slatePublicationContentRetention(
    value: SlatePublication
): readonly ContentRetentionField[] {
    return contentRetentionFields([["materialization", value.materialization]]);
}
